# jnp.einsum, jnp.einsum_path and tensor contractions.
# Expected values come from jax 0.12.0.1 (generated by a script; floats as hex literals).
est_inputs <- function(dtype = NULL) {
  list(
    A = as_jax(array(c(0.25, 0.25, 0.75, -0.25, 0.5, 0.5), c(2, 3)), dtype),
    B = as_jax(array(c(-0.25, 1.25, -1.75, 1.5, 0.0, -1.75, 1.75, 0.25, -2.0, -0.5, 1.75, 1.25), c(3, 4)), dtype),
    C = as_jax(array(c(1.0, 1.0, 0.0, 0.25, 1.5, -1.5, -0.25, -2.0, 2.0, 0.5, -1.0, 0.5, 1.25, -1.5, 1.0, 0.5, -0.25, 1.75, -0.25, 0.5), c(4, 5)), dtype),
    D = as_jax(array(c(1.75, -0.5, 0.75, 0.75, -1.25, 0.75, -0.25, -1.75, 0.75, -1.5), c(5, 2)), dtype),
    S = as_jax(array(c(-0.75, -0.25, -1.25, -0.5, 2.0, -1.25, 0.25, -1.5, 0.5), c(3, 3)), dtype),
    T = as_jax(array(c(-1.0, -1.5, -1.5, 0.5, -0.5, -1.5, -0.25, 2.0, 0.75, 1.0, 1.25, -0.75, -1.0, -0.25, -1.5, -1.75, -1.5, -1.5, -1.25, 2.0, -1.25, -0.75, 1.25, -0.75), c(2, 3, 4)), dtype),
    U = as_jax(array(c(-0.25, 0.75, 0.25, 0.25, -1.5, -2.0, -0.75, 1.0, -1.75, -0.75, -1.0, -2.0, 0.25, 0.75, 0.75, 1.75, 0.75, -1.25, 0.0, 1.25, 1.75, -1.0, -1.5, -1.0), c(2, 4, 3)), dtype),
    V = as_jax(c(0.25, 0.25, 0.25), dtype),
    W = as_jax(c(-1.0, 1.75, -0.25, 1.5), dtype),
    Q = as_jax(array(c(0.75, 1.5, -0.25, 1.25, 1.0, -2.0, 1.5, 1.75, 0.75, -0.75, 0.75, 0.5, -0.5, 0.0, -0.75, 0.25, 0.5, -0.75), c(3, 3, 2)), dtype),
    P = as_jax(array(c(0.5, -0.25, 0.25, -1.5, 0.5, -1.5, -0.25, 1.5, 0.25, 1.75, -0.25, 1.5, -1.5, 1.25, 0.25, 0.75, 1.5, -1.25, -0.75, 0.75, 0.5, 2.0, -0.5, 0.5), c(2, 1, 3, 4)), dtype),
    O = as_jax(array(c(-1.5, 1.0, 0.0, 0.75, 0.25, 1.25, 2.0, -1.25, -1.25, 1.0, -0.25, -2.0, 1.25, 0.25, -0.5, 0.75, 1.0, -0.5, 1.75, -1.25, 1.5, 1.5, -1.75, -1.75, 0.25, 0.25, 1.5, -2.0, 0.5, -0.75, -1.75, -0.5, -1.0, -1.0, -1.25, -0.25, -1.25, 1.75, 0.5, 1.75), c(5, 4, 2)), dtype),
    K = as_jax(array(c(1.0, -0.0), c(2, 1)), dtype),
    Z = as_jax(array(c(-1.0, -0.5, 0.25, -0.25, -1.75, -1.25, -1.0, -1.25, 1.5, -0.75, 0.75, 0.75, -1.75, -2.0, 2.0, 0.75, -0.25, -1.0), c(3, 2, 3)), dtype),
    E1 = as_jax(array(c(-2.0, 0.5, 1.0, 1.5, -0.75, -1.0, -0.5, 1.25, 0.25, -1.25, 1.25, 1.75), c(2, 6)), dtype),
    E2 = as_jax(array(c(0.75, 1.0, 0.0, -0.25, -1.0, -1.5, -1.25, -1.0, -2.0, -0.5, 0.25, 0.0, 1.75, -1.25, -1.25, -0.25, 1.5, -1.5), c(6, 3)), dtype)
  )
}
est_stack_loop <- function(f, x, axis = 0L) {
  n <- dim(x)[axis + 1L]
  jnp_stack(lapply(seq_len(n) - 1L, function(i) f(lax_index_in_dim(x, i, axis, keepdims = FALSE))))
}
test_that("einsum matches JAX on single, pairwise and multi operand contractions", {
  skip_if_no_backend()
  e <- est_inputs()
  Vb <- as_jax(c(0.5, -1.5), "float32")
  At <- jnp_transpose(e$A)
  expect_jax_equal(jnp_einsum("ij,jk->ik", e$A, e$B), array(c(0, -0x1.4000000000000p+0, -0x1.0000000000000p-1, -0x1.0000000000000p-1, -0x1.8000000000000p-2, -0x1.4000000000000p-1, 0x1.d000000000000p+0, 0x1.0000000000000p-4), c(2, 4)), dtype = "float32", tolerance = 1e-5)
  expect_jax_equal(jnp_einsum("ij,jk", e$A, e$B), array(c(0, -0x1.4000000000000p+0, -0x1.0000000000000p-1, -0x1.0000000000000p-1, -0x1.8000000000000p-2, -0x1.4000000000000p-1, 0x1.d000000000000p+0, 0x1.0000000000000p-4), c(2, 4)), dtype = "float32", tolerance = 1e-5)
  expect_jax_equal(jnp_einsum("ii", e$S), 0x1.c000000000000p+0, dtype = "float32", tolerance = 1e-5)
  expect_jax_equal(jnp_einsum("ii->i", e$S), c(-0x1.8000000000000p-1, 2, 0x1.0000000000000p-1), dtype = "float32", tolerance = 1e-5)
  expect_jax_equal(jnp_einsum("ij->ji", e$A), array(c(0x1.0000000000000p-2, 0x1.8000000000000p-1, 0x1.0000000000000p-1, 0x1.0000000000000p-2, -0x1.0000000000000p-2, 0x1.0000000000000p-1), c(3, 2)), dtype = "float32", tolerance = 1e-5)
  expect_jax_equal(jnp_einsum("ij->", e$A), 2, dtype = "float32", tolerance = 1e-5)
  expect_jax_equal(jnp_einsum("i,j->ij", e$V, e$W), array(c(-0x1.0000000000000p-2, -0x1.0000000000000p-2, -0x1.0000000000000p-2, 0x1.c000000000000p-2, 0x1.c000000000000p-2, 0x1.c000000000000p-2, -0x1.0000000000000p-4, -0x1.0000000000000p-4, -0x1.0000000000000p-4, 0x1.8000000000000p-2, 0x1.8000000000000p-2, 0x1.8000000000000p-2), c(3, 4)), dtype = "float32", tolerance = 1e-5)
  expect_jax_equal(jnp_einsum("i,i", e$V, e$V), 0x1.8000000000000p-3, dtype = "float32", tolerance = 1e-5)
  expect_jax_equal(jnp_einsum("bij,bjk->bik", e$T, e$U), array(c(0x1.5000000000000p+1, 0x1.e000000000000p+0, 0x1.e000000000000p+1, 0x1.b000000000000p+1, 0x1.c000000000000p+0, 0x1.e000000000000p-1, 0x1.a000000000000p-1, 0x1.c000000000000p-2, 0x1.2000000000000p-1, -5, 0x1.8000000000000p-3, 0x1.8000000000000p-3, -0x1.4000000000000p-1, 0x1.5000000000000p+1, -0x1.e000000000000p+0, 0x1.9000000000000p+1, -0x1.3800000000000p+2, 0x1.9800000000000p+1), c(2, 3, 3)), dtype = "float32", tolerance = 1e-5)
  expect_jax_equal(jnp_einsum("bij,bjk->bki", e$T, e$U), array(c(0x1.5000000000000p+1, 0x1.e000000000000p+0, 0x1.a000000000000p-1, 0x1.c000000000000p-2, -0x1.4000000000000p-1, 0x1.5000000000000p+1, 0x1.e000000000000p+1, 0x1.b000000000000p+1, 0x1.2000000000000p-1, -5, -0x1.e000000000000p+0, 0x1.9000000000000p+1, 0x1.c000000000000p+0, 0x1.e000000000000p-1, 0x1.8000000000000p-3, 0x1.8000000000000p-3, -0x1.3800000000000p+2, 0x1.9800000000000p+1), c(2, 3, 3)), dtype = "float32", tolerance = 1e-5)
  expect_jax_equal(jnp_einsum("...ij,...jk->...ik", e$P, e$O), array(c(-0x1.4000000000000p+0, 0x1.4000000000000p+1, 0x1.2000000000000p+1, 1, -0x1.3000000000000p+0, -0x1.6000000000000p-1, -1, -0x1.c000000000000p-2, 0x1.9000000000000p+0, -0x1.0000000000000p-3, 0x1.0000000000000p-2, 0x1.7000000000000p+2, 0x1.8000000000000p-1, 0x1.4000000000000p+1, -0x1.0000000000000p-2, -0x1.2000000000000p+1, 0x1.a000000000000p-1, 0x1.8000000000000p-2, -0x1.c000000000000p-2, -0x1.8000000000000p+0, -0x1.d000000000000p+0, 0x1.3400000000000p+2, -0x1.c000000000000p+1, 0x1.2000000000000p+2, 0x1.3800000000000p+1, -0x1.d800000000000p+1, 0x1.8000000000000p-3, -0x1.3800000000000p+1, -0x1.0000000000000p-2, 0x1.2000000000000p+0, 0x1.c000000000000p+1, -0x1.3000000000000p+1, 0x1.0800000000000p+1, 0x1.4000000000000p-2, -0x1.8000000000000p-3, -0x1.4000000000000p+1, 0x1.0000000000000p-3, 0x1.4000000000000p-2, 0x1.c000000000000p-1, -0x1.7000000000000p+0, -0x1.0000000000000p-3, -0x1.d000000000000p+1, 0, -0x1.4000000000000p+1, -0x1.4000000000000p-2, 0x1.e000000000000p+0, -0x1.4000000000000p-2, 0x1.e000000000000p+1, 0x1.c000000000000p-2, 0x1.c000000000000p-1, -0x1.d000000000000p+0, 0x1.8000000000000p-3, 0x1.0000000000000p-2, 0, -0x1.6000000000000p+1, 0x1.c000000000000p+0, -0x1.6000000000000p+1, 0x1.3800000000000p+2, -0x1.3800000000000p+1, 0x1.e000000000000p-1), c(2, 5, 3, 2)), dtype = "float32", tolerance = 1e-5)
  expect_jax_equal(jnp_einsum("...ii->...i", e$S), c(-0x1.8000000000000p-1, 2, 0x1.0000000000000p-1), dtype = "float32", tolerance = 1e-5)
  expect_jax_equal(jnp_einsum("iij->j", e$Q), c(0x1.4000000000000p+1, -0x1.8000000000000p+0), dtype = "float32", tolerance = 1e-5)
  expect_jax_equal(jnp_einsum("iji->j", e$Z), c(-0x1.0000000000000p-2, -0x1.0000000000000p-1), dtype = "float32", tolerance = 1e-5)
  expect_jax_equal(jnp_einsum("ijk,ikj->", e$T, e$U), -0x1.a000000000000p+0, dtype = "float32", tolerance = 1e-5)
  expect_jax_equal(jnp_einsum("ij,ij->i", e$A, e$A), c(0x1.c000000000000p-1, 0x1.8000000000000p-2), dtype = "float32", tolerance = 1e-5)
  expect_jax_equal(jnp_einsum("ij,kj->ikj", e$A, e$A), array(c(0x1.0000000000000p-4, 0x1.0000000000000p-4, 0x1.0000000000000p-4, 0x1.0000000000000p-4, 0x1.2000000000000p-1, -0x1.8000000000000p-3, -0x1.8000000000000p-3, 0x1.0000000000000p-4, 0x1.0000000000000p-2, 0x1.0000000000000p-2, 0x1.0000000000000p-2, 0x1.0000000000000p-2), c(2, 2, 3)), dtype = "float32", tolerance = 1e-5)
  expect_jax_equal(jnp_einsum("ij,jk->ik", e$K, e$B), array(c(-0x1.8000000000000p-1, 0, -0x1.0000000000000p-2, 0, 0, 0, 0x1.4000000000000p+1, 0), c(2, 4)), dtype = "float32", tolerance = 1e-5)
  expect_jax_equal(jnp_einsum("ij,jk,kl->il", e$A, e$B, e$C), array(c(-0x1.8000000000000p-5, -0x1.bc00000000000p+0, -0x1.6400000000000p+1, -0x1.1800000000000p+0, 0x1.0800000000000p+0, -0x1.0c00000000000p+1, 0x1.4800000000000p+0, -0x1.6800000000000p+0, 0x1.0000000000000p-3, -0x1.8000000000000p-2), c(2, 5)), dtype = "float32", tolerance = 1e-5)
  expect_jax_equal(jnp_einsum("ab,bc,cd,de->ae", e$A, e$B, e$C, e$D), array(c(0x1.7180000000000p+1, -0x1.2940000000000p+2, -0x1.7c00000000000p-2, 0x1.1280000000000p+1), c(2, 2)), dtype = "float32", tolerance = 1e-5)
  expect_jax_equal(jnp_einsum("ij,jk,kl,lm,mn->in", e$A, e$B, e$C, e$D, e$E1), array(c(-0x1.7d60000000000p+2, 0x1.4b90000000000p+3, 0x1.2a40000000000p+1, -0x1.6d80000000000p+0, -0x1.cb40000000000p+0, 0x1.56c0000000000p+0, -0x1.e840000000000p+0, 0x1.4030000000000p+2, 0x1.2f80000000000p+0, -0x1.ebc0000000000p+1, 0x1.7ac0000000000p+1, -0x1.06c0000000000p+1), c(2, 6)), dtype = "float32", tolerance = 1e-5)
  expect_jax_equal(jnp_einsum("ii,ij,jk->k", e$S, e$S, e$B), c(0x1.3f00000000000p+3, 0x1.1300000000000p+2, 0x1.7500000000000p+2, 0x1.9600000000000p+1), dtype = "float32", tolerance = 1e-5)
  expect_jax_equal(jnp_einsum("bij,bjk,b->bik", e$T, e$U, Vb), array(c(0x1.5000000000000p+0, -0x1.6800000000000p+1, 0x1.e000000000000p+0, -0x1.4400000000000p+2, 0x1.c000000000000p-1, -0x1.6800000000000p+0, 0x1.a000000000000p-2, -0x1.5000000000000p-1, 0x1.2000000000000p-2, 0x1.e000000000000p+2, 0x1.8000000000000p-4, -0x1.2000000000000p-2, -0x1.4000000000000p-2, -0x1.f800000000000p+1, -0x1.e000000000000p-1, -0x1.2c00000000000p+2, -0x1.3800000000000p+1, -0x1.3200000000000p+2), c(2, 3, 3)), dtype = "float32", tolerance = 1e-5)
  expect_jax_equal(jnp_einsum("i...->...", e$T), array(c(-0x1.4000000000000p+1, -1, -2, 0x1.c000000000000p+0, 0x1.c000000000000p+0, 0x1.0000000000000p-1, -0x1.4000000000000p+0, -0x1.a000000000000p+1, -3, 0x1.8000000000000p-1, -2, 0x1.0000000000000p-1), c(3, 4)), dtype = "float32", tolerance = 1e-5)
  expect_jax_equal(jnp_einsum("...,...", e$V, e$V), c(0x1.0000000000000p-4, 0x1.0000000000000p-4, 0x1.0000000000000p-4), dtype = "float32", tolerance = 1e-5)
  expect_jax_equal(jnp_einsum("ij...,jk...->ik", e$Z, e$U), array(c(0x1.0000000000000p-3, -0x1.8000000000000p-1, -0x1.7000000000000p+0, 0x1.9000000000000p+1, -0x1.2000000000000p+0, -0x1.2000000000000p+2, -0x1.5000000000000p+1, 0x1.4000000000000p+0, 0x1.e400000000000p+2, 0x1.4000000000000p-2, 0x1.2000000000000p+1, -1), c(3, 4)), dtype = "float32", tolerance = 1e-5)
  expect_jax_equal(jnp_einsum("ba,ab", e$A, At), 0x1.4000000000000p+0, dtype = "float32", tolerance = 1e-5)
  expect_jax_equal(jnp_einsum("ij,jk,kl,lm,mn->in", e$A, e$B, e$C, e$D, e$E1, optimize = FALSE), array(c(-0x1.7d60000000000p+2, 0x1.4b90000000000p+3, 0x1.2a40000000000p+1, -0x1.6d80000000000p+0, -0x1.cb40000000000p+0, 0x1.56c0000000000p+0, -0x1.e840000000000p+0, 0x1.4030000000000p+2, 0x1.2f80000000000p+0, -0x1.ebc0000000000p+1, 0x1.7ac0000000000p+1, -0x1.06c0000000000p+1), c(2, 6)), dtype = "float32", tolerance = 1e-5)
  expect_jax_equal(jnp_einsum("ij,jk,kl,lm,mn->in", e$A, e$B, e$C, e$D, e$E1, optimize = TRUE), array(c(-0x1.7d60000000000p+2, 0x1.4b90000000000p+3, 0x1.2a40000000000p+1, -0x1.6d80000000000p+0, -0x1.cb40000000000p+0, 0x1.56c0000000000p+0, -0x1.e840000000000p+0, 0x1.4030000000000p+2, 0x1.2f80000000000p+0, -0x1.ebc0000000000p+1, 0x1.7ac0000000000p+1, -0x1.06c0000000000p+1), c(2, 6)), dtype = "float32", tolerance = 1e-5)
  expect_jax_equal(jnp_einsum("ij,jk,kl,lm,mn->in", e$A, e$B, e$C, e$D, e$E1, optimize = "greedy"), array(c(-0x1.7d60000000000p+2, 0x1.4b90000000000p+3, 0x1.2a40000000000p+1, -0x1.6d80000000000p+0, -0x1.cb40000000000p+0, 0x1.56c0000000000p+0, -0x1.e840000000000p+0, 0x1.4030000000000p+2, 0x1.2f80000000000p+0, -0x1.ebc0000000000p+1, 0x1.7ac0000000000p+1, -0x1.06c0000000000p+1), c(2, 6)), dtype = "float32", tolerance = 1e-5)
  expect_jax_equal(jnp_einsum("ij,jk,kl,lm,mn->in", e$A, e$B, e$C, e$D, e$E1, optimize = "optimal"), array(c(-0x1.7d60000000000p+2, 0x1.4b90000000000p+3, 0x1.2a40000000000p+1, -0x1.6d80000000000p+0, -0x1.cb40000000000p+0, 0x1.56c0000000000p+0, -0x1.e840000000000p+0, 0x1.4030000000000p+2, 0x1.2f80000000000p+0, -0x1.ebc0000000000p+1, 0x1.7ac0000000000p+1, -0x1.06c0000000000p+1), c(2, 6)), dtype = "float32", tolerance = 1e-5)
  expect_jax_equal(jnp_einsum(",ij,jk->ik", 2, e$A, e$B, optimize = "greedy"), array(c(0, -0x1.4000000000000p+1, -1, -1, -0x1.8000000000000p-1, -0x1.4000000000000p+0, 0x1.d000000000000p+1, 0x1.0000000000000p-3), c(2, 4)), dtype = "float32", tolerance = 1e-5)
  expect_jax_equal(jnp_einsum("ij,,jk,kl,lm,mn->in", e$A, 0.5, e$B, e$C, e$D, e$E1), array(c(-0x1.7d60000000000p+1, 0x1.4b90000000000p+2, 0x1.2a40000000000p+0, -0x1.6d80000000000p-1, -0x1.cb40000000000p-1, 0x1.56c0000000000p-1, -0x1.e840000000000p-1, 0x1.4030000000000p+1, 0x1.2f80000000000p-1, -0x1.ebc0000000000p+0, 0x1.7ac0000000000p+0, -0x1.06c0000000000p+0), c(2, 6)), dtype = "float32", tolerance = 1e-5)
  expect_jax_equal(jnp_einsum("ij,,jk,kl,lm,mn->in", e$A, 0.5, e$B, e$C, e$D, e$E1, optimize = "greedy"), array(c(-0x1.7d60000000000p+1, 0x1.4b90000000000p+2, 0x1.2a40000000000p+0, -0x1.6d80000000000p-1, -0x1.cb40000000000p-1, 0x1.56c0000000000p-1, -0x1.e840000000000p-1, 0x1.4030000000000p+1, 0x1.2f80000000000p-1, -0x1.ebc0000000000p+0, 0x1.7ac0000000000p+0, -0x1.06c0000000000p+0), c(2, 6)), dtype = "float32", tolerance = 1e-5)
  expect_jax_equal(jnp_einsum("ij,jk,kl->il", e$A, e$B, e$C, optimize = list(c(0L, 2L), c(0L, 1L))), array(c(-0x1.8000000000000p-5, -0x1.bc00000000000p+0, -0x1.6400000000000p+1, -0x1.1800000000000p+0, 0x1.0800000000000p+0, -0x1.0c00000000000p+1, 0x1.4800000000000p+0, -0x1.6800000000000p+0, 0x1.0000000000000p-3, -0x1.8000000000000p-2), c(2, 5)), dtype = "float32", tolerance = 1e-5)
  expect_jax_equal(jnp_einsum(e$A, c(0, 1), e$B, c(1, 2), c(0, 2)), array(c(0, -0x1.4000000000000p+0, -0x1.0000000000000p-1, -0x1.0000000000000p-1, -0x1.8000000000000p-2, -0x1.4000000000000p-1, 0x1.d000000000000p+0, 0x1.0000000000000p-4), c(2, 4)), dtype = "float32")
  expect_jax_equal(jnp_einsum(e$A, c(0, 1), e$B, c(1, 2)), array(c(0, -0x1.4000000000000p+0, -0x1.0000000000000p-1, -0x1.0000000000000p-1, -0x1.8000000000000p-2, -0x1.4000000000000p-1, 0x1.d000000000000p+0, 0x1.0000000000000p-4), c(2, 4)), dtype = "float32")
  expect_jax_equal(jnp_einsum(e$P, list(ellipsis, 5, 1), e$O, list(ellipsis, 1, 3), list(ellipsis, 5, 3)), array(c(-0x1.4000000000000p+0, 0x1.4000000000000p+1, 0x1.2000000000000p+1, 1, -0x1.3000000000000p+0, -0x1.6000000000000p-1, -1, -0x1.c000000000000p-2, 0x1.9000000000000p+0, -0x1.0000000000000p-3, 0x1.0000000000000p-2, 0x1.7000000000000p+2, 0x1.8000000000000p-1, 0x1.4000000000000p+1, -0x1.0000000000000p-2, -0x1.2000000000000p+1, 0x1.a000000000000p-1, 0x1.8000000000000p-2, -0x1.c000000000000p-2, -0x1.8000000000000p+0, -0x1.d000000000000p+0, 0x1.3400000000000p+2, -0x1.c000000000000p+1, 0x1.2000000000000p+2, 0x1.3800000000000p+1, -0x1.d800000000000p+1, 0x1.8000000000000p-3, -0x1.3800000000000p+1, -0x1.0000000000000p-2, 0x1.2000000000000p+0, 0x1.c000000000000p+1, -0x1.3000000000000p+1, 0x1.0800000000000p+1, 0x1.4000000000000p-2, -0x1.8000000000000p-3, -0x1.4000000000000p+1, 0x1.0000000000000p-3, 0x1.4000000000000p-2, 0x1.c000000000000p-1, -0x1.7000000000000p+0, -0x1.0000000000000p-3, -0x1.d000000000000p+1, 0, -0x1.4000000000000p+1, -0x1.4000000000000p-2, 0x1.e000000000000p+0, -0x1.4000000000000p-2, 0x1.e000000000000p+1, 0x1.c000000000000p-2, 0x1.c000000000000p-1, -0x1.d000000000000p+0, 0x1.8000000000000p-3, 0x1.0000000000000p-2, 0, -0x1.6000000000000p+1, 0x1.c000000000000p+0, -0x1.6000000000000p+1, 0x1.3800000000000p+2, -0x1.3800000000000p+1, 0x1.e000000000000p-1), c(2, 5, 3, 2)), dtype = "float32")
  expect_jax_equal(jnp_einsum("ij,jk->ik", matrix(1:6, 2), e$B), array(c(-0x1.5000000000000p+2, -6, -0x1.d000000000000p+2, -0x1.e000000000000p+2, -0x1.e000000000000p+2, -0x1.e000000000000p+2, 11, 0x1.b000000000000p+3), c(2, 4)), dtype = "float32")
  expect_jax_equal(jnp_einsum("ij,jk->ik", matrix(1:6, 2), matrix(1:12, 3)), array(c(22L, 28L, 49L, 64L, 76L, 100L, 103L, 136L), c(2, 4)), dtype = "int32")
  i8a <- as_jax(array(c(100L, 7L, -100L, 8L, 50L, 9L), c(2, 3)), "int8")
  i8b <- as_jax(array(c(100L, 100L, -128L, 2L, 3L, 1L), c(3, 2)), "int8")
  expect_jax_equal(jnp_einsum("ij,jk->ik", i8a, i8b, preferred_element_type = "int32"), array(c(-6400L, 348L, -50L, 47L), c(2, 2)), dtype = "int32")
  expect_jax_equal(jnp_einsum("ij,jk->ik", i8a, i8b), array(c(0L, 92L, -50L, 47L), c(2, 2)), dtype = "int8")
  expect_jax_equal(jnp_einsum("ij->i", i8a, preferred_element_type = "int32"), c(50L, 24L), dtype = "int32")
  bb <- matrix(c(TRUE, FALSE, TRUE, FALSE, FALSE, TRUE), 2, byrow = TRUE)
  expect_jax_equal(jnp_einsum("ij->i", bb), c(TRUE, TRUE), dtype = "bool")
  expect_jax_equal(jnp_einsum("ij->j", bb), c(TRUE, FALSE, TRUE), dtype = "bool")
  expect_jax_equal(jnp_einsum("ij,ij->ij", bb, bb), array(c(TRUE, FALSE, FALSE, FALSE, TRUE, TRUE), c(2, 3)), dtype = "bool")
  expect_jax_equal(jit(function(a, b, c) jnp_einsum("ij,jk,kl->li", a, b, c))(e$A, e$B, e$C), array(c(-0x1.8000000000000p-5, -0x1.6400000000000p+1, 0x1.0800000000000p+0, 0x1.4800000000000p+0, 0x1.0000000000000p-3, -0x1.bc00000000000p+0, -0x1.1800000000000p+0, -0x1.0c00000000000p+1, -0x1.6800000000000p+0, -0x1.8000000000000p-2), c(5, 2)), dtype = "float32", tolerance = 1e-5)
  expect_error(jnp_einsum("ij->k->i", e$A), "Subscripts can only contain one '->'")
  expect_error(jnp_einsum("i..j->ij", e$A), "Invalid Ellipses")
  expect_error(jnp_einsum("ij->ik", e$A), "Output character 'k' did not appear in the input")
  expect_error(jnp_einsum("ij->ii", e$S), "appeared more than once in the output")
  expect_error(jnp_einsum("ij,jk->ik", e$A), "Number of einsum subscripts, 2, must be equal to the number of operands, 1")
  expect_error(jnp_einsum("ijk->i", e$A), "does not contain the correct number of indices for operand 0")
  expect_error(jnp_einsum("ij,ij->i", e$A, e$B), "Size of label 'i' for operand 1 \\(2\\) does not match previous terms \\(3\\)")
  expect_error(jnp_einsum("ij", e$A, out = 1), class = "jax_not_implemented_error")
  expect_error(jnp_einsum("ij,jk,kl->il", e$A, e$B, e$C, optimize = list(c(0L, 1L, 2L))), "does not support simultaneous contraction of 3 or more operands")
  expect_error(jnp_einsum("ij,jk,kl->il", e$A, e$B, e$C, optimize = "bogus"), "Path optimizer 'bogus' not found")
  expect_error(jnp_einsum("ij...->i", e$A, e$B), "Number of einsum subscripts")
  expect_error(jnp_einsum("...ij,...jk->...ik", e$T, e$B), "does not match previous terms")
})
test_that("einsum_path matches opt_einsum paths and summaries", {
  skip_if_no_backend()
  e <- est_inputs()
  expect_identical(jnp_einsum_path("ij,jk,kl->il", e$A, e$B, e$C, optimize = "auto")[[1L]], list(c(0L, 1L), c(0L, 1L)))
  expect_identical(jnp_einsum_path("ij,jk,kl->il", e$A, e$B, e$C, optimize = TRUE)[[1L]], list(c(0L, 1L), c(0L, 1L)))
  expect_identical(jnp_einsum_path("ij,jk,kl->il", e$A, e$B, e$C, optimize = FALSE)[[1L]], list(c(0L, 1L), c(0L, 1L)))
  expect_identical(jnp_einsum_path("ij,jk,kl->il", e$A, e$B, e$C, optimize = "greedy")[[1L]], list(c(1L, 2L), c(0L, 1L)))
  expect_identical(jnp_einsum_path("ij,jk,kl->il", e$A, e$B, e$C, optimize = "optimal")[[1L]], list(c(0L, 1L), c(0L, 1L)))
  expect_identical(jnp_einsum_path("ab,bc,cd,de->ae", e$A, e$B, e$C, e$D, optimize = "auto")[[1L]], list(c(2L, 3L), c(1L, 2L), c(0L, 1L)))
  expect_identical(jnp_einsum_path("ab,bc,cd,de->ae", e$A, e$B, e$C, e$D, optimize = "greedy")[[1L]], list(c(2L, 3L), c(1L, 2L), c(0L, 1L)))
  expect_identical(jnp_einsum_path("ab,bc,cd,de->ae", e$A, e$B, e$C, e$D, optimize = FALSE)[[1L]], list(c(0L, 1L), c(0L, 1L), c(0L, 1L)))
  expect_identical(jnp_einsum_path("ij,jk,kl,lm,mn->in", e$A, e$B, e$C, e$D, e$E1, optimize = "greedy")[[1L]], list(c(2L, 3L), c(1L, 3L), c(0L, 2L), c(0L, 1L)))
  expect_identical(jnp_einsum_path("ij,jk,kl,lm,mn->in", e$A, e$B, e$C, e$D, e$E1, optimize = "optimal")[[1L]], list(c(2L, 3L), c(1L, 3L), c(0L, 2L), c(0L, 1L)))
  expect_identical(jnp_einsum_path("ii->i", e$S, optimize = "auto")[[1L]], list(c(0L)))
  expect_identical(jnp_einsum_path("ij,jk", e$A, e$B, optimize = "auto")[[1L]], list(c(0L, 1L)))
  expect_identical(jnp_einsum_path("ij,jk", e$A, e$B, optimize = FALSE)[[1L]], list(c(0L, 1L)))
  expect_identical(jnp_einsum_path("ij,ij,ij,jk->ik", e$A, e$A, e$A, e$B, optimize = "greedy")[[1L]], list(c(0L, 1L), c(0L, 2L), c(0L, 1L)))
  expect_identical(jnp_einsum_path("ij,ij,ij,jk->ik", e$A, e$A, e$A, e$B, optimize = "auto")[[1L]], list(c(0L, 1L), c(0L, 2L), c(0L, 1L)))
  expect_identical(jnp_einsum_path("i,j,k,ij,jk->", c(1, 1, 1), rep(1, 4), rep(1, 5), matrix(1, 3, 4), matrix(1, 4, 5), optimize = "greedy")[[1L]], list(c(2L, 4L), c(1L, 3L), c(1L, 2L), c(0L, 1L)))
  expect_identical(jnp_einsum_path(",ij,jk->ik", 2, e$A, e$B, optimize = "greedy")[[1L]], list(c(1L, 2L), c(0L, 1L)))
  expect_identical(jnp_einsum_path("ij,,jk,kl,lm,mn->in", e$A, 0.5, e$B, e$C, e$D, e$E1, optimize = "greedy")[[1L]], list(c(3L, 4L), c(2L, 4L), c(0L, 3L), c(1L, 2L), c(0L, 1L)))
  expect_identical(jnp_einsum_path("ij,jk", e$A, e$B, optimize = "bogus")[[1L]], list(c(0L, 1L)))
  info <- jnp_einsum_path("ij,jk,kl->il", e$A, e$B, e$C, optimize = "greedy")[[2L]]
  expect_identical(info, "  Complete contraction:  ij,jk,kl->il\n         Naive scaling:  4\n     Optimized scaling:  3\n      Naive FLOP count:  3.600e+2\n  Optimized FLOP count:  1.800e+2\n   Theoretical speedup:  2.000e+0\n  Largest intermediate:  1.500e+1 elements\n--------------------------------------------------------------------------------\nscaling        BLAS                current                             remaining\n--------------------------------------------------------------------------------\n   3           GEMM              kl,jk->lj                             ij,lj->il\n   3           GEMM              lj,ij->il                                il->il")
  info <- jnp_einsum_path("bij,bjk,b->bik", e$T, e$U, c(1, 1))[[2L]]
  expect_identical(info, "  Complete contraction:  bij,bjk,b->bik\n         Naive scaling:  4\n     Optimized scaling:  4\n      Naive FLOP count:  2.160e+2\n  Optimized FLOP count:  1.620e+2\n   Theoretical speedup:  1.333e+0\n  Largest intermediate:  1.800e+1 elements\n--------------------------------------------------------------------------------\nscaling        BLAS                current                             remaining\n--------------------------------------------------------------------------------\n   4              0           bjk,bij->bki                            b,bki->bik\n   3              0             bki,b->bik                              bik->bik")
  info <- jnp_einsum_path("ii,i->", e$S, e$V)[[2L]]
  expect_identical(info, "  Complete contraction:  ii,i->\n         Naive scaling:  1\n     Optimized scaling:  1\n      Naive FLOP count:  6.000e+0\n  Optimized FLOP count:  6.000e+0\n   Theoretical speedup:  1.000e+0\n  Largest intermediate:  1.000e+0 elements\n--------------------------------------------------------------------------------\nscaling        BLAS                current                             remaining\n--------------------------------------------------------------------------------\n   1              0                 i,ii->                                    ->")
})
test_that("einsum differentiates, batches and handles mixed dtypes", {
  skip_if_no_backend()
  enable_x64()
  on.exit(enable_x64(FALSE))
  e <- est_inputs("float64")
  check_grad_fd(function(a) jnp_sum(jnp_sin(jnp_einsum("ij,jk->ik", a, e$B))), e$A)
  check_grad_fd(function(s) jnp_einsum("ii", s) * jnp_einsum("ij,ji", s, s), e$S)
  check_grad_fd(function(s) jnp_sum(jnp_einsum("ii->i", s)^2), e$S)
  check_grad_fd(function(t) jnp_sum(jnp_einsum("bij,bjk->bik", t, e$U)^2), e$T)
  check_grad_fd(function(b) jnp_sum(jnp_einsum("ij,jk,kl->il", e$A, b, e$C)^2), e$B)
  check_grad_fd(function(q) jnp_sum(jnp_einsum("iij->j", q)^2), e$Q)
  check_grad_fd(function(p) jnp_sum(jnp_einsum("...ij,...jk->...ik", p, e$O)^2), e$P)
  check_grad_fd(function(b) jnp_sum(grad(function(z) jnp_sum(jnp_sin(jnp_einsum("ij,jk->ik", e$A, z))))(b) * e$B), e$B)
  check_grad_fd(function(s) jnp_sum(grad(function(z) jnp_einsum("ij,jk,ki->", z, z, z))(s) * e$S), e$S)
  f <- function(a) jnp_einsum("ij,jk->ki", a, e$B)
  expect_jax_equal(vmap(f)(e$U), est_stack_loop(f, e$U))
  g <- function(b, c) jnp_einsum("ij,jk,kl->il", e$A, b, c)
  bs <- jnp_stack(list(e$B, e$B * 2))
  expect_jax_equal(vmap(g, in_axes = list(0L, NULL))(bs, e$C), jnp_stack(list(g(e$B, e$C), g(e$B * 2, e$C))))
  expect_jax_equal(jnp_einsum("ij,jk->ik", as_jax(e$A, "float32"), e$B), array(c(0, -0x1.4000000000000p+0, -0x1.0000000000000p-1, -0x1.0000000000000p-1, -0x1.8000000000000p-2, -0x1.4000000000000p-1, 0x1.d000000000000p+0, 0x1.0000000000000p-4), c(2, 4)), dtype = "float64")
  expect_jax_equal(jnp_einsum("i,i->", c(1L, 2L, 3L), as_jax(c(0.5, 0.25, 2), "float32")), 7, dtype = "float32")
  zc <- c(complex(real = 1, imaginary = 2), complex(real = -0.5, imaginary = 1), complex(real = 3, imaginary = -1))
  expect_jax_equal(jnp_einsum("i,i->", zc, e$V), c(complex(real = 0x1.c000000000000p-1, imaginary = 0x1.0000000000000p-1)), dtype = "complex128")
  expect_jax_equal(jnp_einsum("i,j->ij", zc, zc), array(c(complex(real = -3, imaginary = 4), complex(real = -0x1.4000000000000p+1, imaginary = 0), complex(real = 5, imaginary = 5), complex(real = -0x1.4000000000000p+1, imaginary = 0), complex(real = -0x1.8000000000000p-1, imaginary = -1), complex(real = -0x1.0000000000000p-1, imaginary = 0x1.c000000000000p+1), complex(real = 5, imaginary = 5), complex(real = -0x1.0000000000000p-1, imaginary = 0x1.c000000000000p+1), complex(real = 8, imaginary = -6)), c(3, 3)), dtype = "complex128")
  expect_jax_equal(jnp_einsum("ij,jk->ik", as_jax(e$A, "float32"), as_jax(e$B, "float32"), preferred_element_type = "float64"), array(c(0, -0x1.4000000000000p+0, -0x1.0000000000000p-1, -0x1.0000000000000p-1, -0x1.8000000000000p-2, -0x1.4000000000000p-1, 0x1.d000000000000p+0, 0x1.0000000000000p-4), c(2, 4)), dtype = "float64")
  expect_jax_equal(jnp_einsum("ij,jk->ik", e$A, e$B), array(c(0, -0x1.4000000000000p+0, -0x1.0000000000000p-1, -0x1.0000000000000p-1, -0x1.8000000000000p-2, -0x1.4000000000000p-1, 0x1.d000000000000p+0, 0x1.0000000000000p-4), c(2, 4)), dtype = "float64")
})
test_that("tensordot, matvec, vecmat and vecdot match JAX", {
  skip_if_no_backend()
