  expect_jax_equal(jnp_tensordot(e$T, e$U, axes = list(c(1, 2), c(2, 1))), array(c(-0x1.b000000000000p+0, -0x1.7000000000000p+2, -0x1.5000000000000p+0, 0x1.0000000000000p-4), c(2, 2)), dtype = "float32", tolerance = 1e-5)
