  expect_jax_equal(jnp_tensordot(matrix(1:6, 2), e$B, 1), array(c(-0x1.5000000000000p+2, -6, -0x1.d000000000000p+2, -0x1.e000000000000p+2, -0x1.e000000000000p+2, -0x1.e000000000000p+2, 11, 0x1.b000000000000p+3), c(2, 4)), dtype = "float32")
  expect_jax_equal(jnp_tensordot(matrix(1:6, 2), matrix(1:6, 2), list(c(0, 1), c(0, 1)), preferred_element_type = "float32"), 91, dtype = "float32")
