  expect_jax_equal(jnp_vecmat(e$V, e$B), c(-0x1.8000000000000p-3, -0x1.0000000000000p-4, 0, 0x1.4000000000000p-1), dtype = "float32", tolerance = 1e-5)
  expect_jax_equal(jnp_vecmat(e$A, e$B), array(c(0, -0x1.4000000000000p+0, -0x1.0000000000000p-1, -0x1.0000000000000p-1, -0x1.8000000000000p-2, -0x1.4000000000000p-1, 0x1.d000000000000p+0, 0x1.0000000000000p-4), c(2, 4)), dtype = "float32", tolerance = 1e-5)
  expect_jax_equal(jnp_vecdot(e$A, e$A), c(0x1.c000000000000p-1, 0x1.8000000000000p-2), dtype = "float32", tolerance = 1e-5)
  expect_jax_equal(jnp_vecdot(e$T, e$W), array(c(-0x1.1000000000000p+0, 0x1.0200000000000p+3, 0x1.5000000000000p+0, 0x1.2000000000000p-1, 0x1.3c00000000000p+2, -0x1.2000000000000p-1), c(2, 3)), dtype = "float32", tolerance = 1e-5)
  expect_jax_equal(jnp_vecdot(e$A, e$A, axis = 0), c(0x1.0000000000000p-3, 0x1.4000000000000p-1, 0x1.0000000000000p-1), dtype = "float32", tolerance = 1e-5)
  expect_jax_equal(jnp_vecdot(matrix(1:6, 2), c(1L, 0L, 2L)), c(11L, 14L), dtype = "int32")
  zc <- c(complex(real = 1, imaginary = 2), complex(real = -0.5, imaginary = 1), complex(real = 3, imaginary = -1))
  expect_jax_equal(jnp_vecdot(zc, zc), c(complex(real = 0x1.0400000000000p+4, imaginary = 0)), dtype = "complex64")
  expect_jax_equal(jnp_vecmat(zc, e$B), c(complex(real = -0x1.8800000000000p+2, imaginary = -0x1.4000000000000p+1), complex(real = -0x1.e000000000000p+1, imaginary = -0x1.3000000000000p+2), complex(real = -0x1.1800000000000p+2, imaginary = -0x1.7000000000000p+2), complex(real = 0x1.3000000000000p+1, imaginary = 0x1.0000000000000p-1)), dtype = "complex64", tolerance = 1e-5)
  expect_jax_equal(jnp_matvec(e$S, zc), c(complex(real = 0x1.0000000000000p-2, imaginary = -0x1.2000000000000p+1), complex(real = -0x1.7000000000000p+2, imaginary = 3), complex(real = 0x1.c000000000000p-1, imaginary = -0x1.1000000000000p+2)), dtype = "complex64", tolerance = 1e-5)
  expect_error(jnp_vecdot(e$A, e$B), "axes must match")
  expect_error(jnp_matvec(e$A, e$W), "inconsistent size for core dimension")
  expect_jax_equal(jit(function(a, b) jnp_vecdot(a, b, axis = 1))(e$T, e$T), array(c(0x1.c000000000000p+1, 0x1.3000000000000p+2, 0x1.1800000000000p+1, 0x1.6400000000000p+2, 0x1.6000000000000p+2, 0x1.5800000000000p+2, 0x1.2c00000000000p+2, 0x1.4800000000000p+2), c(2, 4)), dtype = "float32", tolerance = 1e-5)
  enable_x64()
  on.exit(enable_x64(FALSE))
  e <- est_inputs("float64")
  check_grad_fd(function(t) jnp_sum(jnp_tensordot(t, e$U, axes = list(c(1, 2), c(2, 1)))^2), e$T)
  check_grad_fd(function(b) jnp_sum(jnp_matvec(b, e$W)^2) + jnp_sum(jnp_vecmat(e$V, b)^3), e$B)
  check_grad_fd(function(t) jnp_sum(jnp_sin(jnp_vecdot(t, e$T, axis = 0))), e$T)
  f <- function(t) jnp_tensordot(t, e$C, 1)
  expect_jax_equal(vmap(f, in_axes = 2L)(e$U), est_stack_loop(f, e$U, 2L))
  expect_jax_equal(vmap(jnp_vecdot)(e$A, e$A), jnp_vecdot(e$A, e$A))
  expect_jax_equal(jnp_tensordot(e$T, as_jax(e$C, "float32"), 1), array(c(-0x1.9000000000000p+0, 1, -0x1.1000000000000p+0, 0x1.5000000000000p+0, 0x1.1000000000000p+0, -0x1.3800000000000p+1, 0x1.a000000000000p+0, -0x1.2600000000000p+3, -0x1.0000000000000p-1, 0x1.3000000000000p+0, -0x1.3000000000000p+2, 0x1.8000000000000p-1, -0x1.c000000000000p+0, -0x1.8000000000000p-1, -0x1.c000000000000p+0, 0x1.7000000000000p+1, 0x1.c000000000000p+0, -0x1.2000000000000p+1, -0x1.4000000000000p+1, -0x1.0800000000000p+2, -0x1.4800000000000p+2, -3, -0x1.b000000000000p+1, -0x1.5000000000000p+1, -0x1.2000000000000p-1, 0x1.3c00000000000p+2, 0x1.7000000000000p+0, 0x1.b000000000000p+0, 0x1.a800000000000p+1, -0x1.e000000000000p-1), c(2, 3, 5)), dtype = "float64")
})
test_that("einsum and tensordot keep weak types as JAX", {
  skip_if_no_backend()
  expect_identical(jaxR:::aval_of(jnp_einsum(",->", 2, 3))$weak, TRUE)
  expect_identical(dtype(jnp_einsum(",->", 2, 3)), "float32")
  expect_identical(jaxR:::aval_of(jnp_tensordot(2, 3, 0))$weak, TRUE)
  expect_identical(dtype(jnp_tensordot(2, 3, 0)), "float32")
  expect_identical(jaxR:::aval_of(jnp_einsum("i,i->", c(1, 2), c(3, 4)))$weak, FALSE)
  expect_identical(dtype(jnp_einsum("i,i->", c(1, 2), c(3, 4))), "float32")
  expect_identical(jaxR:::aval_of(jnp_einsum("ij->", matrix(1:4, 2)))$weak, FALSE)
  expect_identical(dtype(jnp_einsum("ij->", matrix(1:4, 2))), "int32")
})
